from typing import *

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    ROWS, COLS = len(grid), len(grid[0])
    start, goal = (start[0], start[1]), (goal[0], goal[1])
    DIRS = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def hasValue(row, col):
        return not (0 <= row < ROWS and 0 <= col < COLS) or grid[row][col] == "#"

    def dfs(start, visited):
        r, c = start[0], start[1]
        if (r, c) == goal:
            return True
        visited.add((r, c))
        result = False
        for dr, dc in DIRS:
            next_spot_r, next_spot_c = r + dr, c + dc
            if (next_spot_r, next_spot_c) not in visited and not hasValue(
                next_spot_r, next_spot_c
            ):
                if dfs((next_spot_r, next_spot_c), visited):
                    result = True
                    break
        if result:
            visited.add((r, c))
        return result

    visited_cells = set()
    if not dfs(start, visited_cells):
        return []
    path = [start]
    while len(visited_cells) > 0:
        cur_r, cur_c = path[-1]
        has_result = False
        for dr, dc in DIRS:
            next_spot_r, next_spot_c = cur_r + dr, cur_c + dc
            if (next_spot_r, next_spot_c) in visited_cells:
                path.append((next_spot_r, next_spot_c))
                visited_cells.remove((next_spot_r, next_spot_c))
                has_result = True
                break
        if not has_result:
            path.pop()
    return path

