```python
from collections import defaultdict

def solve(n, edges, s, t):
    # Initialize distance values
    INF = float('inf')
    dist = defaultdict(lambda: INF)
    dist[s] = 0  # Distance from source node to source node is 0

    # Initialize set of visited nodes
    visited = set()

    # Create adjacency list for the graph
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    # Relax edges repeatedly to find shortest paths
    for _ in range(n - 1):
        for u in adj:
            if dist[u] == INF:
                continue
            for v, w in adj[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w

    # Check if the destination node is reachable
    if t in dist:
        return dist[t]
    else:
        return -1  # Destination node is unreachable
