import collections
import heapq

Row = int
Col = int
Cell = tuple[Row, Col]
Grid = list[str]
Path = list[Cell]
Pos = tuple[Row, Col]

def solve(grid: Grid, start: Pos, goal: Pos) -> Path:
    @dataclass
    class CellWithDist:
        cell: Cell
        dist: int
    def dists_from(s: Pos) -> collections.defaultdict[Pos, int]:
        def bfs(s: Pos) -> dict[Pos, int]:
            dists: dict[Pos, int] = {s: 0}
            queue: list[Pos] = [s]
            while queue:
                curr = queue.pop()
                neighbours = list(filter(
                    lambda pos: is_free(pos),
                    get_neighbours(curr),
                ))
                for neigh in neighbours:
                    d = dists[curr] + 1
                    if neigh not in dists or d < dists[neigh]:
                        dists[neigh] = d
                        queue.append(neigh)
            return dists
        def is_free(pos: Pos) -> bool:
            row, col = pos
            return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] != '#'
        def get_neighbours(pos: Pos) -> list[Pos]:
            row, col = pos
            return [ (row + dr, col + dc) for dr, dc in [ (0, 1), (1, 0), (0, -1), (-1, 0) ] ]
        return bfs(s)
    def get_search_fn(cell: Cell) -> collections.defaultdict[Pos, int]:
        dists_from_target = dists_from(goal)
        dists_from_start = dists_from(start)
        return lambda other: dists_from_start[other] + dists_from_target[other]
    def search_with_heuristic(start: Cell) -> Path:
        # A* search
        frontier = [CellWithDist(start, 0)]
        explored = set[start]
        get_dist = get_search_fn(start)
        while frontier:
            curr_cell_with_dist = heapq.heappop(frontier)
            curr_cell = curr_cell_with_dist.cell
            curr_dist = curr_cell_with_dist.dist
            if curr_cell == goal:
                return [start] + path
