    def neighbors(board: List[int], pos: int):
        row, col = pos // C, pos % C
        for drow, dcol in ((0, -1), (-1, 0), (0, 1), (1, 0)):
            neighbour = row + drow, col + dcol
            if (
                0 <= neighbour[0] < R
                and 0 <= neighbour[1] < C
                and board[neighbour[0] * C + neighbour[1]] != " "
            ):
                yield board, neighbour

    cost = {(r, c): 1 for r in range(R) for c in range(C)}

    def dijkstra(start: Sequence[int]) -> List[int]:
        # 1) Initialization
        path_len = [float("inf")] * N
        path_len[position := grid.index(start[0])] = 0
        visited = [False] * (R * C)
        predecessor = [None] * N

        # 2) Iterations
        for _ in range(N):
            # choose unvisited with lowest path_cost
            u = min((pos, len) for (pos, len) in enumerate(path_len) if not visited)[0]
            visited[u] = True
            # collect neighbors
            for board, (x, y) in neighbors(grid, u):
                v = x * C + y
                if not visited[v]:
                    alt = path_len[u] + cost[v]
                    if alt < path_len[v]:
                        predecessor[v] = u
                        path_len[v] = alt

        # 3) Finishing
        return predecessor

    for board, ns in neighbors(grid, start[1]):
        if ns == goal[1]:
            return [start, goal]

    path = dijkstra(start[1])

    if not path or path[-1] != goal[1] - start[1]:
        return path
