def all_moves(grid, current):
    row, col = current
    moves = []
    if row > 0 and grid[row - 1][col] == ".":
        moves.append((row - 1, col))
    if row < len(grid) - 1 and grid[row + 1][col] == ".":
        moves.append((row + 1, col))
    if col > 0 and grid[row][col - 1] == ".":
        moves.append((row, col - 1))
    if col < len(grid[0]) - 1 and grid[row][col + 1] == ".":
