    # Convert the grid to a graph using adjacency list representation
    grid_graph = {}
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '.':
                grid_graph[(i, j)] = []
                for dx, dy in (1, 0), (-1, 0), (0, 1), (0, -1):
                    if 0 <= i + dx < len(grid) and 0 <= j + dy < len(grid[0]) and grid[i + dx][j + dy] == '.':
                        grid_graph[(i, j)].append((i + dx, j + dy))

    # Implement depth-first search to find a path from start to goal
    def dfs(current, visited, path):
        visited.add(current)
        path.append(current)

        if current == goal:
            return path

        for neighbor in grid_graph[current]:
            if neighbor not in visited:
                result = dfs(neighbor, visited, path)
                if result is not None:
                    return result

        path.pop()
        return None

    # Find a path using DFS and return the result
    start_cell, goal_cell = start, goal
    path = dfs(start_cell, set(), [])
    return path if goal_cell in path else []
